# The following code is used to generate the summary
def generate_summary(text):
    summary = []
    for i in range(len(text)):
        if i == 0:
            summary.append(text[i])
        elif i == len(text) - 1:
            summary.append(text[i])
        else:
            if text[i] =='':
                summary.append(text[i])
            else:
                summary.append(text[i])
    return summary
